  insert into lessons (module_id, title, slug, content, sort_order, is_published) values
    (mid, $S$Step 1: Decide on Your Legal Structure$S$, $S$step-1-decide-on-your-legal-structure$S$, $C$<p><em>(Step 1: Decide on Legal Structure)</em></p><h2><strong>Instructions</strong></h2><p>Review each entity type below. Score or highlight the ones that best fit your situation. Use the <strong>Notes</strong> section to capture your thoughts or questions for an attorney/CPA.</p><table><tr><td><p><strong>Entity Type</strong></p></td><td><p><strong>Best For</strong></p></td><td><p><strong>Pros</strong></p></td><td><p><strong>Cons</strong></p></td><td><p><strong>Typical Costs</strong></p></td><td><p><strong>Compliance Level</strong></p></td><td><p><strong>Notes</strong></p></td></tr><tr><td><p><strong>Sole Proprietorship</strong></p></td><td><p>Freelancers, side hustles, one-person businesses testing ideas quickly</p></td><td><p>Easiest + cheapest to start, no formal filing required</p></td><td><p>No liability protection, taxed as personal income, harder to raise money</p></td><td><p>$0 (no state filing, just DBA/fictitious name if using one)</p></td><td><p>Low</p></td><td></td></tr><tr><td><p><strong>LLC (Single-Member)</strong></p></td><td><p>Service businesses, consultants, product sellers wanting liability protection</p></td><td><p>Protects personal assets, flexible taxes, simple to run</p></td><td><p>More paperwork than Sole Prop, annual fees</p></td><td><p>$50–$500 state filing fee + annual fee</p></td><td><p>Medium</p></td><td></td></tr><tr><td><p><strong>LLC (Multi-Member)</strong></p></td><td><p>Partnerships, family-owned businesses, small teams</p></td><td><p>Same benefits as single-member, but shares ownership</p></td><td><p>Risk of disputes if no operating agreement, must split profits</p></td><td><p>$50–$500 state filing fee + annual fee</p></td><td><p>Medium</p></td><td></td></tr><tr><td><p><strong>C-Corp</strong></p></td><td><p>Startups planning to raise venture capital, issue stock, or scale nationally</p></td><td><p>Attractive to investors, unlimited shareholders, easier to raise capital</p></td><td><p>Double taxation (corp + personal), higher admin burden</p></td><td><p>$100–$1,000 filing + legal setup</p></td><td><p>High</p></td><td></td></tr><tr><td><p><strong>S-Corp (Tax Election)</strong></p></td><td><p>Small LLCs or Corps with $40k–$60k+ profit looking to save on self-employment tax</p></td><td><p>Avoids double taxation, saves on self-employment taxes</p></td><td><p>Must file as Corp, stricter IRS rules, limited to 100 shareholders</p></td><td><p>Same as LLC or Corp filing</p></td><td><p>Medium–High</p></td><td></td></tr><tr><td><p><strong>Nonprofit (501(c)(3))</strong></p></td><td><p>Social impact orgs, community programs, education, faith-based</p></td><td><p>Tax-exempt status, eligible for grants/donations</p></td><td><p>Heavy compliance, can’t distribute profits to owners, must have board</p></td><td><p>$100–$1,000 filing + IRS 1023 ($275–$600)</p></td><td><p>High</p></td><td></td></tr><tr><td><p><strong>DBA (Doing Business As)</strong></p></td><td><p>Business wanting to operate under a different name than its legal entity</p></td><td><p>Cheap way to brand multiple lines under one entity</p></td><td><p>No liability protection (DBA isn’t an entity)</p></td><td><p>$10–$100 depending on state/county</p></td><td><p>Low</p></td><td></td></tr></table><h2><strong>Quick Recommendations</strong></h2><ul><li><strong>Solo service-based business:</strong> LLC (Single-Member)</li><li><strong>Partnership:</strong> LLC (Multi-Member) with Operating Agreement</li><li><strong>Startup seeking investors:</strong> C-Corp, possibly S-Corp election later</li><li><strong>Retail / Product Sales:</strong> LLC + Sales Tax Permit</li><li><strong>Nonprofit mission-driven:</strong> Nonprofit (501(c)(3)) with board of directors</li><li><strong>Testing fast &amp; lean:</strong> Sole Prop or DBA (upgrade later)</li></ul><h2><strong>Notes Section</strong></h2><ul><li>Which entity feels most aligned with your goals?</li><li>Do you plan to raise outside funding?</li><li>Do you need to protect personal assets immediately?</li><li>Will you operate in multiple states.</li></ul>$C$, 1, true),
    (mid, $S$Step 3: Register the Business Entity$S$, $S$step-3-register-the-business-entity$S$, $C$<p><strong>Includes:</strong> Step‑by‑Step Guide + Operating Agreement (LLC) + Articles of Organization (LLC – generic) + Corporate Bylaws (Corp – short form) + Filing Tracker Worksheet + Initial Resolutions (LLC/Corp)</p><h2><strong>📘 Step‑by‑Step Guide (Any State)</strong></h2><p><strong>Prereqs (5–10 mins):</strong></p><ul><li>✅ Name cleared (Step 3)</li><li>✅ Business address (can be a commercial virtual office if allowed in your state)</li><li>✅ Registered Agent (in‑state street address; person or service)</li><li>✅ Owner list + ownership % (LLC) / initial directors (Corp)</li><li>✅ Management model (LLC): Member‑Managed or Manager‑Managed</li><li>✅ Payment method for filing fees</li></ul><p><strong>A. File with the Secretary of State</strong></p><ol><li>Go to your state’s “Business Services” / “Corporations” portal</li><li>Choose entity type: <strong>LLC</strong> or <strong>Corporation</strong> (C‑Corp; S‑Corp is a tax election later)</li><li>Complete the online form (or PDF):<ol><li>Exact legal name</li><li>Principal office address</li><li>Registered Agent name + physical address</li><li>LLC Management: Member‑Managed <strong>or</strong> Manager‑Managed</li><li>Corporation: Initial registered office + initial directors (if required)</li><li>Effective date (immediate or delayed)</li><li>Organizer/Incoporator signature</li></ol></li><li>Pay state filing fee (typically $50–$500)</li><li>Download <strong>filed Articles</strong> and <strong>state certificate</strong> (Approval/Formation/Status)</li></ol><p><strong>B. Post‑Filing Essentials (Same Day)</strong><br /> 6) Create your <strong>internal governance docs</strong>:</p><ul><li><strong>LLC:</strong> Operating Agreement (template below)</li><li><strong>Corp:</strong> Bylaws (template below) + Initial Board Resolutions (template below)</li></ul><ol><li>Build your <strong>ownership ledger</strong>:<ol><li><strong>LLC:</strong> Schedule of Members (names, contributions, % interest)</li><li><strong>Corp:</strong> Stock ledger + share issuance (board approval)</li></ol></li><li>Move to <strong>Step 5 (EIN)</strong>, then open a <strong>business bank account</strong></li><li>Calendar your <strong>Annual Report</strong> due date (Step 8 compliance calendar)</li></ol><p><strong>C. Special Situations</strong></p><ul><li><strong>Multi‑State operations:</strong> If you transact in another state (employees, storefront, regular sales activity), file a <strong>Foreign Qualification</strong> in that state.</li><li><strong>Nonprofit:</strong> Bylaws + Board, then IRS Form 1023/1023‑EZ (handled in Pot 07 as needed).</li><li><strong>S‑Corp election:</strong> If electing S‑Corp taxation, file IRS <strong>Form 2553</strong> (usually within 75 days of formation or start of the tax year).</li></ul><div class="lesson-template"><h3>📄 Template for this lesson</h3><p>Download and use the worksheet that goes with this lesson:</p><a class="dl" href="/templates/documents-legal/step-3-4-template-initial-resolutions-fill-in.docx" download="Step 3.4 Template Initial Resolutions (Fill‑in).docx">⬇ Download Initial Resolutions (Fill-in)</a></div>$C$, 2, true),
    (mid, $S$Step 4: Apply for Your EIN$S$, $S$step-4-apply-for-your-ein$S$, $C$<h2><strong>📘 Step-by-Step Guide: Apply for EIN Online</strong></h2><p><strong>Time Required:</strong> 15 minutes<br /> <strong>Cost:</strong> Free</p><ol><li>Go to IRS.gov → Apply for EIN Online.<ol><li>Hours: Monday–Friday, 7 AM–10 PM EST.</li></ol></li><li>Select <strong>“Apply Online Now.”</strong></li><li>Choose your <strong>entity type</strong>:<ol><li>LLC (Single or Multi-Member)</li><li>Corporation (C-Corp or S-Corp later)</li><li>Sole Proprietor (can still get EIN)</li><li>Nonprofit Organization</li></ol></li><li>Enter business details:<ol><li>Legal name (exact match to Articles)</li><li>Responsible party (owner, officer, trustee)</li><li>Business address (no P.O. boxes)</li></ol></li><li>Choose how you want to receive your EIN confirmation:<ol><li><strong>PDF download</strong> immediately (recommended).</li></ol></li><li>Submit application → receive your <strong>EIN letter (CP 575)</strong> instantly.</li></ol><p><strong>Checklist of Online Application Screens:</strong></p><ul><li>Select “Begin Application”</li><li>Choose entity type (LLC, Corporation, etc.)</li><li>Enter number of members (if LLC)</li><li>Confirm location (U.S.)</li><li>Provide reason for applying: ☐ Started new business ☐ Banking ☐ Hired employees</li><li>Responsible Party: Name + SSN/ITIN</li><li>Business details: Name + Address + State</li><li>Confirm tax year end (default = Dec 31)</li><li>Delivery method: <strong>Electronic (PDF)</strong></li></ul><p><strong>Important Notes:</strong></p><ul><li>Save EIN letter <strong>immediately</strong>—IRS does not email a second copy.</li><li>Print two copies: one for banking, one for compliance binder.</li></ul><h2><strong>EIN Confirmation Storage Checklist</strong></h2><p><strong>Where to Store EIN Letter (CP 575):</strong><br /> ☐ Business Bank Account Folder (digital copy)<br /> ☐ Compliance Binder (printed copy)<br /> ☐ Cloud Drive → /01_Documentation_Legal/EIN<br /> ☐ Shared with CPA/Bookkeeper</p><p><strong>Who Needs Access:</strong><br /> ☐ Founders / Officers<br /> ☐ Accountant or CPA<br /> ☐ Bank Relationship Manager</p><h2><strong>Form SS-4 Fill Guide (For Mail/Fax Applications)</strong></h2><p><strong>Use:</strong> If online system unavailable, or if owner lacks SSN/ITIN (e.g., foreign owners).</p><p><strong>Key Fields:</strong></p><ul><li><strong>1:</strong> Legal name of entity (must match state filings)</li><li><strong>2:</strong> Trade name / DBA (if any)</li><li><strong>3–4:</strong> Responsible Party: Name, SSN/ITIN/EIN</li><li><strong>5–6:</strong> Mailing address + physical location</li><li><strong>8a–8c:</strong> Entity type (LLC, Corp, Nonprofit, etc.)</li><li><strong>9a:</strong> Reason for applying (check: “Started a new business”)</li><li><strong>10:</strong> Date business started (state formation date)</li><li><strong>11:</strong> Closing month of accounting year (Dec = default)</li><li><strong>12:</strong> First wages paid (leave blank if none yet)</li><li><strong>16:</strong> Industry activity description (choose NAICS code)</li><li><strong>18:</strong> # of employees expected in next 12 months (enter estimate or 0)</li></ul><p><strong>Filing Method:</strong></p><ul><li>Fax to IRS: (855) 641-6935 (fastest for U.S.)</li><li>Mail to IRS: Internal Revenue Service, Attn: EIN Operation, Cincinnati, OH 45999</li></ul><p><strong>Processing Time:</strong></p><ul><li>Fax: 4–7 business days</li><li>Mail: 4–6 weeks</li></ul><h2><strong>⚡ Best Practices for EIN</strong></h2><ul><li>Always use EIN (not SSN) when opening bank accounts or vendor relationships.</li><li>If you plan to elect <strong>S-Corp status</strong>, file IRS <strong>Form 2553</strong> within 75 days of formation.</li><li>Keep EIN letter in <strong>three places</strong>: digital, physical, and with CPA.</li><li>EIN is public on tax filings—protect other identifiers (SSN, ITIN).</li></ul>$C$, 3, true),
    (mid, $S$Step 6: Business Licenses & Permits$S$, $S$step-6-business-licenses-permits$S$, $C$<p><strong>Includes:</strong> Business License Checklist + Permit Tracker Worksheet + Resale Certificate Guide</p><h2><strong>📘 Step-by-Step Guide</strong></h2><ol><li><strong>Check Local Requirements</strong><ol><li>Contact your <strong>city or county clerk’s office</strong> or check their website for “Business License” or “Occupational License.”</li></ol></li><li><strong>Check State Requirements</strong><ol><li>Visit your <strong>State Department of Revenue</strong> for sales tax permits / resale certificates.</li><li>Contact your <strong>State Licensing Board</strong> for industry-specific licenses (healthcare, construction, cosmetology, finance, etc.).</li></ol></li><li><strong>Check Federal Requirements (if applicable)</strong><ol><li>Use the SBA’s guide: Apply for Licenses &amp; Permits.</li><li>Federal licensing applies only in regulated industries (alcohol, firearms, broadcasting, aviation, agriculture, transportation, etc.).</li></ol></li><li><strong>Apply + Pay Fees</strong><ol><li>Expect fees ranging from $25–$1,000 depending on type and level of license.</li></ol></li><li><strong>Track and Renew</strong><ol><li>Many licenses expire annually or biannually. Always track renewal deadlines.</li></ol></li></ol><h2><strong>📑 TEMPLATE 1: Business License Checklist</strong></h2><p><strong>Local Level</strong><br /> ☐ General Business License (city/county)<br /> ☐ Zoning or Home Occupation Permit (if working from home)<br /> ☐ Health Department Permit (restaurants, food handling, healthcare)<br /> ☐ Fire Safety Inspection (for physical locations open to the public)</p><p><strong>State Level</strong><br /> ☐ Sales Tax Permit / Reseller’s Permit / Resale Certificate<br /> ☐ Professional or Occupational License (contractors, barbers, healthcare, finance, legal, etc.)<br /> ☐ Environmental Permit (manufacturing, disposal, emissions, etc.)</p><p><strong>Federal Level (only for regulated industries)</strong><br /> ☐ Alcohol, Tobacco, Firearms (ATF)<br /> ☐ Federal Communications Commission (telecom, broadcasting)<br /> ☐ Department of Agriculture (food, meat, produce)<br /> ☐ Department of Transportation (trucking, shipping, logistics)</p><h2><strong>📑 TEMPLATE 2: Permit Tracker Worksheet</strong></h2><table><tr><td><p><strong>License/Permit</strong></p></td><td><p><strong>Issuing Agency</strong></p></td><td><p><strong>Application Date</strong></p></td><td><p><strong>Fee</strong></p></td><td><p><strong>Approval Date</strong></p></td><td><p><strong>Expiration/Renewal Date</strong></p></td><td><p><strong>Notes</strong></p></td></tr><tr><td><p>Business License</p></td><td><p>Local Clerk</p></td><td><p>[ ]</p></td><td><p>$[ ]</p></td><td><p>[ ]</p></td><td><p>[ ]</p></td><td><p>Annual renewal</p></td></tr><tr><td><p>Reseller’s Permit</p></td><td><p>State Dept. of Revenue</p></td><td><p>[ ]</p></td><td><p>$[ ]</p></td><td><p>[ ]</p></td><td><p>[ ]</p></td><td><p>Track for tax filings</p></td></tr><tr><td><p>Contractor License</p></td><td><p>State Licensing Board</p></td><td><p>[ ]</p></td><td><p>$[ ]</p></td><td><p>[ ]</p></td><td><p>[ ]</p></td><td><p>CE credits required</p></td></tr><tr><td><p>Federal Permit</p></td><td><p>Federal Agency</p></td><td><p>[ ]</p></td><td><p>$[ ]</p></td><td><p>[ ]</p></td><td><p>[ ]</p></td><td><p>Biennial update</p></td></tr></table><h2><strong>📑 TEMPLATE 3: Resale Certificate Guide</strong></h2><p><strong>Purpose</strong><br /> Allows a business to purchase inventory tax-free and collect sales tax from customers.</p><p><strong>Universal Application Steps</strong></p><ol><li>Visit your <strong>State Department of Revenue</strong> website.</li><li>Search for “Resale Certificate,” “Sales Tax Permit,” or “Seller’s Permit.”</li><li>Complete application (common fields include):<ol><li>Business legal name (must match your entity)</li><li>EIN (from Step 5)</li><li>Business type (retail, wholesale, e-commerce, service with product sales)</li><li>Estimated monthly/annual sales volume</li></ol></li><li>Receive certificate or permit (instant download or mailed).</li></ol><p><strong>Best Practices</strong></p><ul><li>Always keep a copy on file for vendors.</li><li>Check whether renewal is required (varies by state).</li><li>If selling online, research <strong>economic nexus laws</strong>: you may need multiple permits if sales exceed certain thresholds in other states.</li></ul><div class="lesson-template"><h3>📄 Template for this lesson</h3><p>Download and use the worksheet that goes with this lesson:</p><a class="dl" href="/templates/documents-legal/rev-filllable-service-agreement-template.pdf" download="rev filllable Service Agreement Template.pdf">⬇ Download Service Agreement Template (Fillable)</a></div>$C$, 4, true),
    (mid, $S$Step 7: Ongoing Compliance Guide$S$, $S$step-7-ongoing-compliance-guide$S$, $C$<h2><strong>📘 Step-by-Step Guide</strong></h2><ol><li><strong>Annual Requirements (Universal)</strong><ol><li>File <strong>Annual Report / Statement of Information</strong> with your Secretary of State.</li><li>Pay any renewal fees (LLC/Corp/Nonprofit).</li><li>Renew licenses &amp; permits (from Step 7).</li><li>File <strong>taxes</strong> (federal + state, and sales tax if applicable).</li></ol></li><li><strong>Maintain Internal Records</strong><ol><li>Keep updated <strong>Operating Agreement / Bylaws</strong>.</li><li>Keep minutes of major meetings/decisions.</li><li>Maintain ownership or membership ledger.</li></ol></li><li><strong>Stay in Good Standing</strong><ol><li>Request a <strong>Certificate of Good Standing</strong> from your state yearly (many banks and funders require it).</li></ol></li><li><strong>Calendar All Deadlines</strong><ol><li>Add recurring reminders (30–60 days before) for annual filings, tax dates, and license renewals.</li></ol></li></ol><h2><strong>🔑 Best Practices</strong></h2><ul><li>Set <strong>two reminders per deadline</strong>: one 60 days before, one 15 days before.</li><li>Keep <strong>scanned + physical copies</strong> of filings.</li><li>Even if not required, hold an <strong>annual review meeting</strong>—this creates a paper trail for compliance.</li><li>Use your <strong>Registered Agent service dashboard</strong> (if you hire one) to simplify compliance tracking.</li><li>Treat compliance as a <strong>funding prerequisite</strong>—banks, investors, and grantors check it first.</li></ul><div class="lesson-template"><h3>📄 Template for this lesson</h3><p>Download and use the worksheet that goes with this lesson:</p><a class="dl" href="/templates/documents-legal/compliance-calendar-and-checklist.docx" download="Compliance Calendar and Checklist.docx">⬇ Download Compliance Calendar & Checklist</a></div>$C$, 5, true);
